"""Fixed Composio endpoint and closed sets of browser operations."""
import json
from urllib.request import Request, build_opener, HTTPRedirectHandler

from vault.store import AccessError

TOOLS = frozenset('BROWSER_USE_' + name for name in (
    'CREATE_PROFILE', 'START_RUN', 'GET_RUN_STATUS', 'GET_RUN',
    'LIST_RUN_EVENTS', 'GET_BROWSER_SESSION', 'CANCEL_RUN',
    'STOP_BROWSER_SESSION', 'DELETE_PROFILE',
))
BROWSER_TOOL_TOOLS = frozenset('BROWSER_TOOL_' + name for name in (
    'CREATE_TASK', 'WATCH_TASK', 'GET_SESSION', 'STOP_TASK', 'GET_OUTPUT_FILE',
))


class NoRedirects(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class ComposioBrowserClient:
    def __init__(self, settings, api_key):
        self.settings = settings
        self.api_key = api_key

    def execute(self, slug, arguments):
        if slug not in TOOLS:
            raise AccessError('Only the configured Browser Use operations are available.', 403)
        payload = {
            'connected_account_id': self.settings['connected_account_id'],
            'user_id': self.settings['connection_user_id'],
            'version': self.settings['tool_version'],
            'arguments': arguments,
        }
        request = Request('https://backend.composio.dev/api/v3.1/tools/execute/' + slug,
            data=json.dumps(payload).encode(), method='POST',
            headers={'x-api-key': self.api_key, 'Content-Type': 'application/json'})
        try:
            with build_opener(NoRedirects()).open(request, timeout=30) as response:
                result = json.load(response)
        except Exception:
            # HTTP bodies and exception strings can contain passwords or control URLs.
            raise AccessError('The Browser Use request failed. Its outcome may be unknown; do not repeat a task with side effects.', 502) from None
        if result.get('successful') is not True or not isinstance(result.get('data'), dict):
            raise AccessError('Composio did not confirm successful Browser Use execution.', 502)
        return result['data']


class ComposioBrowserToolClient:
    """Use the For You consumer project, scoped to Browser Tool only.

    The CLI is used for operator login/setup. Native requests keep vault values
    out of the CLI's argument history and local response artifacts.
    """
    def __init__(self, settings, api_key):
        self.settings = settings
        self.api_key = api_key
        self.router_session_id = None

    def post(self, route, payload):
        request = Request('https://backend.composio.dev/api/v3.1/' + route,
            data=json.dumps(payload).encode(), method='POST', headers={
                'x-user-api-key': self.api_key,
                'x-org-id': self.settings['organization_id'],
                'x-project-id': self.settings['project_id'],
                'Content-Type': 'application/json',
            })
        try:
            with build_opener(NoRedirects()).open(request, timeout=45) as response:
                return json.load(response)
        except Exception:
            raise AccessError('The Browser Tool request was not acknowledged. Check its outcome before repeating external work.', 502) from None

    def execute(self, slug, arguments):
        if slug not in BROWSER_TOOL_TOOLS:
            raise AccessError('Only Browser Tool operations are available.', 403)
        if self.router_session_id is None:
            session = self.post('tool_router/session', {
                'user_id': self.settings['connection_user_id'],
                'toolkits': {'enable': ['browser_tool']},
                'tools': {'browser_tool': {'enable': sorted(BROWSER_TOOL_TOOLS)}},
                'instant': False,
                'manage_connections': {'enable': False},
                'workbench': {'enable': False},
                'proxy_execute': {'enable': False},
                'search': {'enable': False},
                'execute': {'enable_multi_execute': False},
            })
            from urllib.parse import quote
            sid = session.get('session_id')
            if not isinstance(sid, str) or not sid:
                raise AccessError('Composio did not return a consumer browser session.', 502)
            config = session.get('config', {})
            if (config.get('instant') is not False or
                    config.get('toolkits', {}).get('enabled') != ['browser_tool'] or
                    set(config.get('tools', {}).get('browser_tool', {}).get('enabled', [])) != BROWSER_TOOL_TOOLS or
                    config.get('workbench', {}).get('enable') is not False):
                raise AccessError('Composio did not confirm the browser-only session restrictions and disabled instant billing.', 503)
            self.router_session_id = quote(sid, safe='')
        result = self.post('tool_router/session/' + self.router_session_id + '/execute',
                           {'tool_slug': slug, 'arguments': arguments})
        # Router execution returns data/error/log_id, unlike direct execute's
        # successful flag. A non-empty error must still fail closed.
        if result.get('error') or result.get('successful') is False or not isinstance(result.get('data'), dict):
            raise AccessError('Composio did not confirm Browser Tool execution. Check the provider before retrying.', 502)
        return result['data']
"""Consumer Browser Tool with backend-owned sessions and scoped vault handoff.

Provider URL reports are not independent DOM inspection. No CDP or OTP-fill
API is documented for this toolkit, so OTP handoff fails before reading a code.
"""
import json
import re
from urllib.parse import urlsplit

from vault.store import AccessError
from .service import CloudBrowser

TERMINAL = {'finished', 'stopped', 'failed'}
STATUS = {'started': 'running', 'finished': 'completed', 'stopped': 'cancelled', 'failed': 'failed'}


class BrowserTool(CloudBrowser):
    profile_retained_on_stop = False

    def state(self, turn):
        key = self.context_key(turn)
        path = self.directory / 'browser-tool-contexts' / (key + '.json')
        return path, json.loads(path.read_text()) if path.exists() else {'sessions': {}, 'threads': {}}

    def execute(self, name, args):
        return self.client.execute('BROWSER_TOOL_' + name, args)

    def watch(self, entry):
        data = self.execute('WATCH_TASK', {'taskId': entry['task_id']})
        if data.get('status') not in STATUS:
            raise AccessError('Browser Tool returned an unrecognized task status.', 502)
        return data

    def status(self, turn, session=None):
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            name, entry = self.selected(turn, state, session)
            if entry.get('dispatch_unknown'):
                raise AccessError('A dispatch was not acknowledged. The operator must reconcile it before another run.', 409)
            if not entry.get('task_id'):
                return {'status': 'idle', 'session': name}
            data = self.watch(entry)
            entry['status'] = data['status']
            self.save(path, state)
            result = self.safe_result(turn, {'status': STATUS[data['status']], 'result': data.get('output', '')})
            result['success'] = data['status'] == 'finished' and data.get('isSuccess') is True
            return {'session': name, **result}

    def start(self, turn, task, session='web', *, credentials=None, origin=None):
        if not isinstance(task, str) or not 10 <= len(task.strip()) <= 20000:
            raise AccessError('Supply a browser task of 10 to 20,000 characters.')
        if not isinstance(session, str) or not re.fullmatch(r'[a-z0-9][a-z0-9_-]{0,39}', session):
            raise AccessError('Use a short lowercase browser session name.')
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            entry = state['sessions'].setdefault(session, {})
            if entry.get('dispatch_unknown'):
                raise AccessError('A previous dispatch was not acknowledged. Ask the operator to reconcile it.', 409)
            if entry.get('task_id'):
                current = self.watch(entry)
                if current['status'] not in TERMINAL:
                    return {'status': STATUS[current['status']], 'session': session,
                            'next': 'Use clanker_browser_status; the existing task is still active.'}
            args = {'task': task}
            if entry.get('session_id'):
                args['sessionId'] = entry['session_id']
            if credentials is not None:
                self.vault.assert_private(turn)
                parsed = urlsplit(origin or '')
                if parsed.scheme != 'https' or not parsed.hostname or parsed.username or '*' in origin:
                    raise AccessError('The saved credential requires an exact HTTPS origin.', 403)
                args.update(startUrl=origin, secrets={origin: credentials})
                cipher = self.vault.store.code_crypto()
                entry['redactions'] = (entry.get('redactions', []) + [
                    cipher.encrypt(credentials.partition(':')[2].encode()).decode()
                ])[-64:]
            state['threads'][self.thread(turn)] = session
            entry['dispatch_unknown'] = True
            self.save(path, state)
            data = self.execute('CREATE_TASK', args)
            sid, tid = data.get('browser_session_id'), data.get('watch_task_id')
            if not all(isinstance(value, str) and value for value in (sid, tid)):
                raise AccessError('Browser Tool did not acknowledge the task and browser IDs. Ask the operator to reconcile it.', 502)
            entry.update(session_id=sid, task_id=tid, status='started', dispatch_unknown=False)
            self.save(path, state)
            return {'status': 'running', 'session': session,
                    'next': 'Use clanker_browser_status until the task ends; verify the reported website result.'}

    def login_origin(self, turn, expected='', *, otp=False):
        self.vault.assert_private(turn)
        if otp:
            raise AccessError('Browser Tool has no verified private OTP-fill API. No code was retrieved or sent.', 503)
        with self.vault.lock_for(turn.home):
            _, state = self.state(turn)
            _, entry = self.selected(turn, state)
            if entry.get('dispatch_unknown') or not entry.get('task_id'):
                raise AccessError('Start the browser and stop at the login page first.', 409)
            data = self.watch(entry)
            if data['status'] not in TERMINAL:
                raise AccessError('Wait for the browser task to finish before requesting credentials.', 409)
            parsed = urlsplit(str(data.get('current_url') or ''))
            if parsed.scheme != 'https' or not parsed.hostname or parsed.username:
                raise AccessError('Browser Tool did not report an HTTPS login origin.', 403)
            origin = parsed.scheme + '://' + parsed.netloc
            if expected and origin != expected:
                raise AccessError('The provider-reported page does not match the saved login origin.', 403)
            return origin

