def id_for_key(key: str) -> str:
    """Stable, opaque handle for retrying a trusted save after a crash."""
    if not isinstance(key, str) or not key or len(key) > 256:
        raise VaultError('invalid idempotency key')
    return 'vault_' + uuid.uuid5(uuid.NAMESPACE_URL, 'hermes-vault:' + key).hex

