"""Fixed Composio endpoint and closed sets of browser operations."""
import json
from urllib.request import Request, build_opener, HTTPRedirectHandler

from vault.store import AccessError

TOOLS = frozenset('BROWSER_USE_' + name for name in (
    'CREATE_PROFILE', 'START_RUN', 'GET_RUN_STATUS', 'GET_RUN',
    'LIST_RUN_EVENTS', 'GET_BROWSER_SESSION', 'CANCEL_RUN',
    'STOP_BROWSER_SESSION', 'DELETE_PROFILE',
))
BROWSER_TOOL_TOOLS = frozenset('BROWSER_TOOL_' + name for name in (
    'CREATE_TASK', 'WATCH_TASK', 'GET_SESSION', 'STOP_TASK', 'GET_OUTPUT_FILE',
))


class NoRedirects(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class TaskInputRejected(AccessError):
    """Confirmed upstream validation rejection before task creation."""
    def __init__(self, log_id=None):
        super().__init__('Browser Tool rejected the task input (HTTP 422); no task was created. '
                         'The existing browser session remains available.', 422)
        self.log_id = log_id if isinstance(log_id, str) and log_id.startswith('log_') else None


def task_input_rejected(result):
    data = result.get('data')
    if not isinstance(data, dict) or data.get('status_code') != 422:
        return False
    if any(data.get(k) for k in ('id', 'task_id', 'taskId', 'watch_task_id', 'browser_session_id')):
        return False
    try:
        detail = json.loads(data.get('message', ''))['detail']
    except (ValueError, TypeError, KeyError):
        return False
    return isinstance(detail, list) and bool(detail) and all(
        isinstance(item, dict) and isinstance(item.get('loc'), list) and
        item['loc'] and item['loc'][0] == 'body' and item.get('type') in
        {'value_error', 'missing', 'string_type', 'string_too_short', 'string_too_long', 'extra_forbidden'}
        for item in detail)


class ComposioBrowserClient:
    def __init__(self, settings, api_key):
        self.settings = settings
        self.api_key = api_key

    def execute(self, slug, arguments):
        if slug not in TOOLS:
            raise AccessError('Only the configured Browser Use operations are available.', 403)
        payload = {
            'connected_account_id': self.settings['connected_account_id'],
            'user_id': self.settings['connection_user_id'],
            'version': self.settings['tool_version'],
            'arguments': arguments,
        }
        request = Request('https://backend.composio.dev/api/v3.1/tools/execute/' + slug,
            data=json.dumps(payload).encode(), method='POST',
            headers={'x-api-key': self.api_key, 'Content-Type': 'application/json'})
        try:
            with build_opener(NoRedirects()).open(request, timeout=30) as response:
                result = json.load(response)
        except Exception:
            # HTTP bodies and exception strings can contain passwords or control URLs.
            raise AccessError('The Browser Use request failed. Its outcome may be unknown; do not repeat a task with side effects.', 502) from None
        if result.get('successful') is not True or not isinstance(result.get('data'), dict):
            raise AccessError('Composio did not confirm successful Browser Use execution.', 502)
        return result['data']


class ComposioBrowserToolClient:
    """Use the For You consumer project, scoped to Browser Tool only.

    The CLI is used for operator login/setup. Native requests keep vault values
    out of the CLI's argument history and local response artifacts.
    """
    def __init__(self, settings, api_key):
        self.settings = settings
        self.api_key = api_key
        self.router_session_id = None

    def post(self, route, payload):
        request = Request('https://backend.composio.dev/api/v3.1/' + route,
            data=json.dumps(payload).encode(), method='POST', headers={
                'x-user-api-key': self.api_key,
                'x-org-id': self.settings['organization_id'],
                'x-project-id': self.settings['project_id'],
                'Content-Type': 'application/json',
            })
        try:
            with build_opener(NoRedirects()).open(request, timeout=45) as response:
                return json.load(response)
        except Exception:
            raise AccessError('The Browser Tool request was not acknowledged. Check its outcome before repeating external work.', 502) from None

    def execute(self, slug, arguments):
        if slug not in BROWSER_TOOL_TOOLS:
            raise AccessError('Only Browser Tool operations are available.', 403)
        if self.router_session_id is None:
            session = self.post('tool_router/session', {
                'user_id': self.settings['connection_user_id'],
                'toolkits': {'enable': ['browser_tool']},
                'tools': {'browser_tool': {'enable': sorted(BROWSER_TOOL_TOOLS)}},
                'instant': False,
                'manage_connections': {'enable': False},
                'workbench': {'enable': False},
                'proxy_execute': {'enable': False},
                'search': {'enable': False},
                'execute': {'enable_multi_execute': False},
            })
            from urllib.parse import quote
            sid = session.get('session_id')
            if not isinstance(sid, str) or not sid:
                raise AccessError('Composio did not return a consumer browser session.', 502)
            config = session.get('config', {})
            if (config.get('instant') is not False or
                    config.get('toolkits', {}).get('enabled') != ['browser_tool'] or
                    set(config.get('tools', {}).get('browser_tool', {}).get('enabled', [])) != BROWSER_TOOL_TOOLS or
                    config.get('workbench', {}).get('enable') is not False):
                raise AccessError('Composio did not confirm the browser-only session restrictions and disabled instant billing.', 503)
            self.router_session_id = quote(sid, safe='')
        result = self.post('tool_router/session/' + self.router_session_id + '/execute',
                           {'tool_slug': slug, 'arguments': arguments})
        # Router execution returns data/error/log_id, unlike direct execute's
        # successful flag. A non-empty error must still fail closed.
        if result.get('error') or result.get('successful') is False or not isinstance(result.get('data'), dict):
            if slug == 'BROWSER_TOOL_CREATE_TASK' and task_input_rejected(result):
                raise TaskInputRejected(result.get('log_id'))
            raise AccessError('Composio did not confirm Browser Tool execution. Check the provider before retrying.', 502)
        return result['data']

